<script setup lang="ts">
import { onMounted,onUnmounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { api,useLoad,useCommand,money,time,PageHeader,StatusBadge,Feedback,type Order,type Payment } from '@tradeflow/ui'
import { pathNo,usePoll } from '../state'
import OrderTimeline from '../components/OrderTimeline.vue'
import CreateRequestRecovery from '../components/CreateRequestRecovery.vue'
let alive=true;onUnmounted(()=>{alive=false})
const no=String(useRoute().params.no),url=`/orders/${pathNo(no)}`,reason=ref(''),notice=ref(''),payment=ref<Payment|null>(null)
const load=useLoad<Order>(s=>api(url,{signal:s})),command=useCommand(`user-order:${no}`)
const allowed=(a:string)=>load.data.value?.allowedActions?.includes(a)
const poll=usePoll(async signal=>{const order=await api<Order>(url,{signal});let p:Payment|null=null;if(order.paymentNo)p=await api<Payment>(`/payments/${pathNo(order.paymentNo)}`,{signal});if(signal.aborted)return true;load.data.value=order;payment.value=p;return !['CREATING','PENDING_PAYMENT','CLOSING','CANCELLING'].includes(order.status)&&(!p||['SUCCEEDED','CLOSED','FAILED'].includes(p.status))})
onMounted(()=>void load.reload())
// 恢复只显示原支付事实，随后GET追踪订单与支付，不触发重新扣款。
function recoveredPayment(value:Payment){if(!alive)return;payment.value=value;notice.value='已找回原支付记录，请以支付状态及订单进度为准。';poll.start()}
// 支付金额及支付号由订单权威提供；受理后仅GET追踪支付和订单两侧事实。
async function pay(){const body={orderNo:no};const result=await command.run<Payment>('pay',body,key=>api('/payments',{method:'POST',body,key}));if(result&&alive){payment.value=result;notice.value='支付请求已受理，正在查询实际结果。';poll.start()}}
async function action(name:'cancel'|'receive'){if(name==='cancel'&&!reason.value.trim())return;const body=name==='cancel'?{reason:reason.value.trim()}:undefined;const result=await command.run(name,body,key=>api(`${url}/${name}`,{method:'POST',body,key}));if(result!==undefined&&alive){notice.value='操作已受理，请以最新订单状态为准。';poll.start()}}
</script>
<template><section><RouterLink class="back-link" to="/orders">← 我的订单</RouterLink><PageHeader title="订单详情" :description="no"><template #actions><button @click="load.reload()">刷新状态</button></template></PageHeader><Feedback :error="load.error.value || command.error.value" :loading="load.loading.value || command.busy.value"/><CreateRequestRecovery :order-no="no" kind="payment" :activity="command.busy.value" @payment="recoveredPayment"/><CreateRequestRecovery :order-no="no" kind="aftersale"/><div v-if="load.data.value" class="two-col"><div><article class="panel"><div class="row spread"><h2>当前进度</h2><StatusBadge :status="load.data.value.status"/></div><dl class="details"><dt>创建时间</dt><dd>{{time(load.data.value.createdAt)}}</dd><dt>库存同步</dt><dd><StatusBadge :status="load.data.value.stockSyncStatus"/></dd><dt>支付截止</dt><dd>{{time(load.data.value.payDeadline)}}</dd><dt>支付状态</dt><dd><StatusBadge v-if="payment" :status="payment.status"/><span v-else>点击刷新查询或提交支付后查看</span></dd></dl><div v-if="load.data.value.shipment" class="shipment"><h3>物流信息</h3><p>{{load.data.value.shipment.carrier}}</p><p class="mono">{{load.data.value.shipment.trackingNo}}</p><p class="small muted">以上为已登记物流，配送轨迹请向承运商查询。</p></div></article><article class="panel"><h2>购买商品</h2><div v-for="item in load.data.value.items" :key="item.orderItemId" class="item-line"><h3>{{item.productName}}</h3><p class="muted">{{item.specification}} · {{item.quantity}} 件</p><strong>{{money(item.unitPriceCents)}} / 件</strong><details><summary>逐件退款权益</summary><div v-for="unit in item.units" :key="unit.unitNo" class="unit-row">第 {{unit.unitNo}} 件 · 剩余 {{money(unit.remainingRefundCents)}} · {{unit.hasActiveAftersale?'已有进行中售后':'无进行中售后'}}<br/>已退款 {{money(unit.succeededRefundCents)}} / 预留 {{money(unit.reservedRefundCents)}}</div></details></div></article></div><aside class="panel summary"><span class="eyebrow">订单金额</span><strong class="large-price">{{money(load.data.value.amountCents)}}</strong><p class="muted">{{load.data.value.currency}}</p><p role="status">{{notice}}</p><Feedback :error="poll.message.value" :loading="poll.running.value"/><div class="stack"><button v-if="allowed('PAY')" class="primary" :disabled="command.busy.value" @click="pay">提交模拟支付</button><button @click="poll.start" :disabled="poll.running.value">查询支付与订单进度</button><button v-if="poll.running.value" @click="poll.stop">停止自动查询</button><button v-if="allowed('RECEIVE')" class="primary" :disabled="command.busy.value" @click="action('receive')">确认收货</button><RouterLink v-if="['UNSHIPPED_FULL','REFUND_ONLY','RETURN_REFUND'].some(allowed)" class="button secondary" :to="`/aftersales/new/${pathNo(no)}`">申请售后</RouterLink></div><form v-if="allowed('CANCEL') || allowed('CANCEL_CREATING')" @submit.prevent="action('cancel')"><label for="cancel-reason">取消原因</label><textarea id="cancel-reason" v-model.trim="reason" maxlength="255" required/><button class="danger-button full" :disabled="command.busy.value">取消订单</button></form><p class="small muted">可用操作来自服务器。提交后状态可能仍需后台处理。</p></aside></div><OrderTimeline :order-no="no"/></section></template>
